insert into transcripts (upload_id, call_id, id, message_id, language, text, segments, model, created_at) values
  ('ad17d113-1294-47ed-8a37-d1f76d47a403', NULL, 'afc6594a-ddb8-4124-8c46-6906f65c153a', NULL, 'en', 'Apex was 7, not 6.', '[{"start":0,"end":2,"text":"Apex was 7, not 6."}]'::jsonb, 'nova-3', '2026-10-10T01:09:05.000Z'),
  ('1a4585bd-f630-4f17-8679-2191100d816d', NULL, 'bb3d94df-3301-4b31-8fe5-7c930b20608f', NULL, 'es+en', 'Okay, Friday, Riverside Block B. Big day on four. We poured the deck on four, like sixty-eight yards, finished about two thirty. Apex had six guys on it. BrightLine, five electricians on three doing the rough-in, I''d say sixty percent. The Delta guys were on two running duct on the east wing. Llovió desde las siete hasta las diez y media, no pudimos hacer block afuera, los de masonry se metieron adentro, perdimos como tres horas y media. Ironclad dropped two loads of rebar around one, three of their guys stayed to tie. Our guys, four of us, cleaning and layout for five. Toolbox talk this morning on wet weather access, no incidents. Monday we need the pump at seven for the level five deck. Ah, y el inspector de la ciudad vino a ver el colado, todo bien, firmó. One more thing, the west stair, the handrail is still missing on three, I put a barricade, we need the steel guys next week. Photos coming, one of the pour and one of the rain this morning so you have it for the record. That''s it, that''s Friday. Have a good weekend.', '[{"start":0,"end":8.2,"text":"Okay, Friday, Riverside Block B. Big day on four."},{"start":8.2,"end":18.9,"text":"We poured the deck on four, like sixty-eight yards, finished about two thirty. Apex had six guys on it."},{"start":18.9,"end":30.5,"text":"BrightLine, five electricians on three doing the rough-in, I''d say sixty percent."},{"start":30.5,"end":41,"text":"The Delta guys were on two running duct on the east wing."},{"start":41,"end":52.3,"text":"Llovió desde las siete hasta las diez y media, no pudimos hacer block afuera, los de masonry se metieron adentro, perdimos como tres horas y media."},{"start":52.3,"end":63,"text":"Ironclad dropped two loads of rebar around one, three of their guys stayed to tie."},{"start":63,"end":74.4,"text":"Our guys, four of us, cleaning and layout for five."},{"start":74.4,"end":86,"text":"Toolbox talk this morning on wet weather access, no incidents."},{"start":86,"end":98.5,"text":"Monday we need the pump at seven for the level five deck."},{"start":98.5,"end":112,"text":"Ah, y el inspector de la ciudad vino a ver el colado, todo bien, firmó."},{"start":112,"end":128,"text":"One more thing, the west stair, the handrail is still missing on three, I put a barricade, we need the steel guys next week."},{"start":128,"end":146,"text":"Photos coming, one of the pour and one of the rain this morning so you have it for the record."},{"start":146,"end":168,"text":"That''s it, that''s Friday. Have a good weekend."}]'::jsonb, 'nova-3', '2026-10-09T22:39:00.000Z'),
  (NULL, '33b39e73-ad97-499d-8fdf-6b7765a31ec3', 'b8851bed-173f-4cbb-8b80-c3312663443d', NULL, 'en', 'Hi Kevin, this is the SiteLog assistant for Kestrel Build Group. This call is recorded for your daily report. Tell me about today. Apex, 3 guys, 8 hours, Ramp B. Shear wall formwork at Level 3, all done. our crew, 8 guys, 8 hours, Level 3. Column pours at Level 2, still going. three of ours, 3 guys, 4 hours, Ramp B. Precast erection at Level 3, still going. Got it. What else? Glazing units, 1 crate came in. No incidents. Here is what I have: Apex Concrete, 3 workers, 8 hours; Kestrel self-perform, 8 workers, 8 hours; Kestrel self-perform, 3 workers, 4 hours. 14 on site, 100 hours in total. Shall I file it? Yes, file it. Filed. The PDF comes by text. Thanks, Kevin.', '[{"start":0,"end":9.5,"speaker":"agent","text":"Hi Kevin, this is the SiteLog assistant for Kestrel Build Group. This call is recorded for your daily report. Tell me about today."},{"start":10,"end":19,"speaker":"reporter","text":"Apex, 3 guys, 8 hours, Ramp B. Shear wall formwork at Level 3, all done."},{"start":19.5,"end":21,"speaker":"reporter","text":"our crew, 8 guys, 8 hours, Level 3."},{"start":21,"end":29,"speaker":"reporter","text":"Column pours at Level 2, still going."},{"start":29,"end":32,"speaker":"reporter","text":"three of ours, 3 guys, 4 hours, Ramp B."},{"start":32,"end":41,"speaker":"reporter","text":"Precast erection at Level 3, still going."},{"start":41.3,"end":49.7,"speaker":"agent","text":"Got it. What else?"},{"start":50,"end":59,"speaker":"reporter","text":"Glazing units, 1 crate came in."},{"start":60,"end":69,"speaker":"reporter","text":"No incidents."},{"start":70,"end":148.5,"speaker":"agent","text":"Here is what I have: Apex Concrete, 3 workers, 8 hours; Kestrel self-perform, 8 workers, 8 hours; Kestrel self-perform, 3 workers, 4 hours. 14 on site, 100 hours in total. Shall I file it?"},{"start":149,"end":152,"speaker":"reporter","text":"Yes, file it."},{"start":153,"end":160,"speaker":"agent","text":"Filed. The PDF comes by text. Thanks, Kevin."}]'::jsonb, 'nova-3', '2026-10-09T22:13:01.000Z'),
  (NULL, '202d6221-345e-4a07-8c18-e2b5d51eda71', '19bde057-9ab2-4ff9-875a-c69b6f1ccba7', NULL, 'en', 'Hi Aisha, this is the SiteLog assistant for Kestrel Build Group. This call is recorded for your daily report. Tell me about today. No incidents. Got it. What else? Rain from 11:00. Rained out; crew released at 11:00. Here is what I have: a weather day, 5 hours lost. Shall I file it? Yes, file it. Filed. The PDF comes by text. Thanks, Aisha.', '[{"start":0,"end":19.5,"speaker":"agent","text":"Hi Aisha, this is the SiteLog assistant for Kestrel Build Group. This call is recorded for your daily report. Tell me about today."},{"start":20,"end":29,"speaker":"reporter","text":"No incidents."},{"start":29.3,"end":40.7,"speaker":"agent","text":"Got it. What else?"},{"start":41,"end":50,"speaker":"reporter","text":"Rain from 11:00. Rained out; crew released at 11:00."},{"start":51,"end":77.5,"speaker":"agent","text":"Here is what I have: a weather day, 5 hours lost. Shall I file it?"},{"start":78,"end":81,"speaker":"reporter","text":"Yes, file it."},{"start":82,"end":89,"speaker":"agent","text":"Filed. The PDF comes by text. Thanks, Aisha."}]'::jsonb, 'nova-3', '2026-10-09T23:42:50.000Z'),
  (NULL, 'b338d7b6-67bd-4940-8326-d58267108da6', 'e658a550-1217-4ea6-89a5-a584b0e68c20', NULL, 'en', 'Hey, this is Luis, covering Elm St. today for Priya. We framed units one through four, six guys, no rain. I''ll send photos.', '[{"start":0,"end":12.5,"text":"Hey, this is Luis, covering Elm St. today for Priya."},{"start":12.5,"end":28,"text":"We framed units one through four, six guys, no rain."},{"start":28,"end":41,"text":"I''ll send photos."}]'::jsonb, 'nova-3', '2026-10-09T22:52:41.000Z');
