-- Generated by `pnpm seed:demo` (packages/shared/src/demo/seed-sql.ts); do not edit by hand.
-- §18.1 as written: Fri Oct 9, 2026.
-- Idempotent: it replaces the rows of the demo orgs (is_demo) and refuses to touch any other org.
-- Demo office users sign in with magic links (or password "sitelog-demo" when password auth is enabled).
begin;

-- Refuse a non-demo org with a demo id ------------------------------------------------------------
do $$
declare v_org record;
begin
  select id, name into v_org from orgs where id in ('7a0cfa5d-2a29-43fb-8665-fcd9bed4106d', '6068578e-a1cb-4424-8ef6-9852a765d8de') and not is_demo limit 1;
  if found then
    raise exception 'seed:demo: org % (%) exists and is not a demo org (is_demo = false); nothing was written', v_org.id, v_org.name
      using errcode = 'P0001';
  end if;
end $$;

-- Office users ------------------------------------------------------------------------------------
on conflict (id) do nothing;

do $$
begin
  if exists (select 1 from pg_tables where schemaname = 'auth' and tablename = 'identities') then
    values (gen_random_uuid(), '3dee836a-fca5-4d0c-8572-5e8e0c3fb25a', '3dee836a-fca5-4d0c-8572-5e8e0c3fb25a', '{"sub":"3dee836a-fca5-4d0c-8572-5e8e0c3fb25a","email":"lena@kestrelbuild.example"}'::jsonb, 'email', now(), now(), now()) on conflict do nothing;
