    values (gen_random_uuid(), '7c264d1c-6256-4ed6-80bb-f718bd40afac', '7c264d1c-6256-4ed6-80bb-f718bd40afac', '{"sub":"7c264d1c-6256-4ed6-80bb-f718bd40afac","email":"accounts@kestrelbuild.example"}'::jsonb, 'email', now(), now(), now()) on conflict do nothing;
    values (gen_random_uuid(), '2f08556a-a238-4334-88d0-e44e3842c21a', '2f08556a-a238-4334-88d0-e44e3842c21a', '{"sub":"2f08556a-a238-4334-88d0-e44e3842c21a","email":"elif@demiryapi.example"}'::jsonb, 'email', now(), now(), now()) on conflict do nothing;
